-- M7 contract DDL v1. Cross-owner UUIDs are references, never foreign keys.
SET LOCAL timezone = 'UTC';
CREATE TABLE escalation.rules (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), code text NOT NULL UNIQUE, level text NOT NULL, delay_seconds integer NOT NULL CHECK(delay_seconds>=0), active boolean NOT NULL DEFAULT true);
GRANT SELECT, INSERT, UPDATE ON escalation.rules TO helpdesk_m7;
CREATE TABLE escalation.jobs (id uuid PRIMARY KEY, version bigint NOT NULL DEFAULT 1 CHECK(version>0), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), ticket_id uuid NOT NULL, attempt_id uuid, expected_version bigint NOT NULL CHECK(expected_version>0), kind text NOT NULL CHECK(kind IN ('AUTO_CLOSE','FOLLOWUP','REMINDER','ESCALATE')), idempotency_key text NOT NULL UNIQUE, due_at timestamptz NOT NULL, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), last_error_code text, CHECK(kind<>'AUTO_CLOSE' OR attempt_id IS NOT NULL));
GRANT SELECT, INSERT, UPDATE ON escalation.jobs TO helpdesk_m7;
CREATE TABLE escalation.idempotency_records (actor_scope text NOT NULL, command text NOT NULL, target text NOT NULL, key text NOT NULL CHECK(length(key) BETWEEN 16 AND 128), payload_digest bytea NOT NULL CHECK(octet_length(payload_digest)=32), response_status integer NOT NULL CHECK(response_status BETWEEN 200 AND 299), response_body jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), expires_at timestamptz NOT NULL, PRIMARY KEY(actor_scope,command,target,key));
CREATE TABLE escalation.outbox (event_id uuid PRIMARY KEY, event_type text NOT NULL, schema_version integer NOT NULL CHECK(schema_version>0), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), occurred_at timestamptz NOT NULL, correlation_id uuid NOT NULL, payload jsonb NOT NULL CHECK(jsonb_typeof(payload)='object'), digest bytea NOT NULL CHECK(octet_length(digest)=32));
CREATE TABLE escalation.outbox_delivery (event_id uuid NOT NULL REFERENCES escalation.outbox(event_id), consumer_id text NOT NULL CHECK(consumer_id ~ '^M[1-9]$'), state text NOT NULL CHECK(state IN ('PENDING','LEASED','ACKED','DEAD_LETTER')), attempts integer NOT NULL DEFAULT 0 CHECK(attempts>=0), lease_until timestamptz, acked_at timestamptz, last_error_code text, PRIMARY KEY(event_id,consumer_id), CHECK((state='ACKED')=(acked_at IS NOT NULL)));
CREATE TABLE escalation.inbox (consumer_id text NOT NULL, event_id uuid NOT NULL, digest bytea NOT NULL CHECK(octet_length(digest)=32), aggregate_id uuid NOT NULL, aggregate_version bigint NOT NULL CHECK(aggregate_version>0), received_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(consumer_id,event_id));
CREATE TABLE escalation.audit_intents (id uuid PRIMARY KEY, actor_id uuid NOT NULL, action text NOT NULL, object_id uuid NOT NULL, scope text NOT NULL, reason text NOT NULL, outcome text NOT NULL, correlation_id uuid NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON escalation.idempotency_records, escalation.outbox, escalation.inbox, escalation.audit_intents TO helpdesk_m7;
GRANT SELECT, INSERT, UPDATE ON escalation.outbox_delivery TO helpdesk_m7;
CREATE INDEX ON escalation.outbox_delivery (state, lease_until, event_id) WHERE state<>'ACKED';
REVOKE ALL ON ALL TABLES IN SCHEMA escalation FROM PUBLIC;
